-- Generated by demo-datagen (Main sql, SingleStoreTables): a change feed per table of brokerage-feeds.sql, each
-- copying its table into brokerage.singlestore (the connector makes the namespace and the table on its first
-- start). demo.sh runs it while Kafka is off and the generator writes these tables (D50, amended 2026-11-24,
-- item 238), with the singlestore user's catalog token and the root password put in, then starts each, and
-- stops them when Kafka is back. Append-only: the generator only ever inserts, so the feed stops at an update.
USE brokerage;

CREATE OR REPLACE PIPELINE brokerage_calendar_to_lake AS LOAD DATA CONNECTOR 'ChangeFeedConnector'
CONFIG '{"singlestore.url": "jdbc:mariadb://localhost:3306/brokerage", "singlestore.user": "root",
         "singlestore.database": "brokerage", "singlestore.table": "calendar", "singlestore.append-only": "true",
         "iceberg.catalog.uri": "http://nuna-catalog:8181", "iceberg.catalog.warehouse": "lakehouse",
         "iceberg.catalog.header.X-Iceberg-Access-Delegation": "vended-credentials",
         "iceberg.namespace": "brokerage.singlestore", "iceberg.table": "calendar", "commit.interval.ms": "15000"}'
CREDENTIALS '{"singlestore.password": "${SINGLESTORE_ROOT_PASSWORD}", "iceberg.catalog.token": "${SINGLESTORE_TOKEN}"}'
BATCH_INTERVAL 1000
REPLACE INTO TABLE lake_commits
FORMAT JSON (
  snapshot_id <- value::snapshot_id, source_table <- value::source_table, iceberg_table <- value::iceberg_table,
  kind <- value::kind, rows_written <- value::rows_written, keys_deleted <- value::keys_deleted,
  offsets <- value::offsets, gap_after <- value::gap_after, @committed_at <- value::committed_at)
SET committed_at = FROM_UNIXTIME(@committed_at / 1000);

